CREATE TABLE [dbo].[ccTimeZoneArea](	  [id_country] SMALLINT NOT NULL	, [area] VARCHAR(10) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [location] VARCHAR(500) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [tz_standard] INT NOT NULL	, [tz_daylight] INT NOT NULL	, [call_record] BIT NULL DEFAULT((1))	, [locality] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NULL)CREATE NONCLUSTERED INDEX [PK_ccTimeZoneArea_1] ON [dbo].[ccTimeZoneArea] ([id_country] ASC, [area] ASC, [location] ASC)INCLUDE ([tz_standard], [tz_daylight], [locality])